25	public class Audit {
26	
27	    private final Path file;
28	
29	    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
30	        this.file = Path.of(path);
31	    }
32	
33	    /** Append one audit record. Tests assert the exact line(s) in the file. */
34	    public synchronized void record(String entry) {
35	        try {
36	            Path parent = file.toAbsolutePath().getParent();
37	            if (parent != null) {
38	                Files.createDirectories(parent);
39	            }
40	            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
41	                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
42	        } catch (IOException e) {
43	            throw new UncheckedIOException(e);
44	        }
45	    }
46	
47	    /** The signed-in user a write names in its X-User header ("" when it names none). */
48	    public static String user(ServerHttpConnection connection) {
49	        HttpHeader header = connection.getRequest().getHeaders().getHeader("X-User");
50	        return header == null ? "" : header.getValue();
51	    }
52	
53	    /** One record: the event, then sheet=<id> and by=<user>, then the fields, separated by single spaces. */
54	    public static String line(String event, String sheetId, String user, String... fields) {
55	        StringBuilder line = new StringBuilder(event).append(" sheet=").append(sheetId)
56	                .append(" by=").append(user == null ? "" : user.trim());
57	        for (String field : fields) {
