152	
153	import java.math.BigDecimal;
154	import java.math.RoundingMode;
155	import java.time.LocalDate;
156	import java.util.LinkedHashMap;
157	import java.util.Map;
158	import java.util.Objects;
159	import net.officefloor.hq.app.claim.Claim;
160	import net.officefloor.hq.app.claim.ClaimStatus;
161	import net.officefloor.hq.app.claim.Claims;
162	import net.officefloor.hq.app.person.Person;
163	import net.officefloor.hq.app.rate.Rates;
164	import net.officefloor.hq.app.sheet.Sheets;
165	import net.officefloor.plugin.variable.Out;
166	import net.officefloor.plugin.variable.Val;
167	
168	public class TakeStatement {
169	    // Records the person's due-total now and binds each of their counting claims to its figure now;
170	    // the rest of their claims are left unbound.
171	    public void take(@Val Person person, Claims claims, Rates rates, Sheets sheets, Statements statements,
172	            Out<Statement> statementOut) {
173	        statements.lock(person.id());
174	        LocalDate today = sheets.today(person.sheetId());
175	        Map<Long, BigDecimal> figures = new LinkedHashMap<>();
176	        for (Claim claim : claims.list(person.sheetId())) {
177	            if (claim.personId() == person.id()
178	                    && (claim.status() == ClaimStatus.OPEN || claim.status() == ClaimStatus.SETTLED)) {
179	                figures.put(claim.id(), figure(claim, person, rates));
180	            }
181	        }
182	        BigDecimal total = figures.values().stream().filter(Objects::nonNull)
183	                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
184	        // With no rate today and no figure, the due-total is n/a.
185	        boolean none = rates.on(person.sheetId(), person.grade(), today) == null
186	                && figures.values().stream().allMatch(Objects::isNull);
187	        claims.bind(person.sheetId(), person.id(), figures);
188	        Statement statement = new Statement(person.sheetId(), person.id(), none ? "n/a" : total.toPlainString(),
189	                figures.size(), today);
190	        statements.add(statement);
191	        statementOut.set(statement);
192	    }
193	
194	    /**
195	     * The claim's figure now (null when it has none): a settled claim's frozen due, otherwise the figure the
196	     * last statement bound it to, otherwise its amount times its person's grade's rate on its date, half to even.
197	     */
198	    private static BigDecimal figure(Claim claim, Person person, Rates rates) {
199	        if (claim.settledDue() != null) {
200	            return claim.settledDue();
201	        }
202	        if (claim.stated()) {
203	            return claim.statedDue();
204	        }
205	        BigDecimal rate = rates.on(claim.sheetId(), person.grade(), claim.date());
206	        return rate == null ? null : claim.amount().multiply(rate).movePointLeft(2).setScale(2, RoundingMode.HALF_EVEN);
207	    }
208	}
