396	public class ApplyClaimStatus {
397	    // Stored only if the claim still has the status it was loaded with, so two users cannot both move it.
398	    public void apply(@PathVariable("status") String status, @Val Claim claim, Claims claims,
399	            People people, Rates rates, ServerHttpConnection connection,
400	            Out<ClaimResponse> responseOut) throws ClaimStatusRefusedException {
401	        ClaimStatus next;
402	        try {
403	            next = ClaimStatus.valueOf(status.trim().toUpperCase());
404	        } catch (IllegalArgumentException e) {
405	            throw new ClaimStatusRefusedException("Not a claim status: " + status);
406	        }
407	        String user = Audit.user(connection).trim();
408	        // Four eyes: the user who opened a claim cannot settle it.
409	        if (next == ClaimStatus.SETTLED && claim.openedBy() != null && claim.openedBy().equals(user)) {
410	            throw new ClaimStatusRefusedException("The user who opened a claim cannot settle it.");
411	        }
412	        Claim changed = claim.status().allows(next)
413	                ? claims.changeStatus(claim, next, due(claim, people, rates), user)
414	                : null;
415	        if (changed == null) {
416	            throw new ClaimStatusRefusedException("A " + claim.status() + " claim cannot become " + next + ".");
417	        }
418	        responseOut.set(ClaimResponse.from(changed));
419	    }
420	
421	    /**
