423	     * person's grade's rate on the claim's date, half to even; null when none applies.
424	     */
425	    private static BigDecimal due(Claim claim, People people, Rates rates) {
426	        if (claim.stated()) {
427	            return claim.statedDue();
428	        }
429	        Person person = people.find(claim.sheetId(), claim.personId());
430	        if (person == null) {
431	            return null;
432	        }
433	        BigDecimal rate = rates.on(claim.sheetId(), person.grade(), claim.date());
434	        return rate == null ? null : claim.amount().multiply(rate).movePointLeft(2).setScale(2, RoundingMode.HALF_EVEN);
435	    }
