685	package net.officefloor.hq.app.claim;
686	
687	import java.math.BigDecimal;
688	import java.sql.Date;
689	import java.sql.PreparedStatement;
690	import java.time.LocalDate;
691	import java.util.List;
692	import org.springframework.dao.DuplicateKeyException;
693	import org.springframework.jdbc.core.JdbcTemplate;
694	import org.springframework.jdbc.core.RowMapper;
695	import org.springframework.jdbc.support.GeneratedKeyHolder;
696	import org.springframework.jdbc.support.KeyHolder;
697	import org.springframework.stereotype.Repository;
698	
699	/** The store of claims, kept per sheet. */
700	@Repository
701	public class Claims {
702	
703	    private static final RowMapper<Claim> ROW = (rs, n) -> new Claim(rs.getLong("id"), rs.getString("sheet_id"),
704	            rs.getLong("person_id"), rs.getBigDecimal("amount"), rs.getObject("claim_date", LocalDate.class),
705	            rs.getString("note"), ClaimStatus.valueOf(rs.getString("status")),
706	            rs.getObject("claim_number", Long.class), rs.getBigDecimal("settled_due"),
707	            rs.getString("opened_by"), rs.getBoolean("stated"), rs.getBigDecimal("stated_due"));
708	
709	    private final JdbcTemplate jdbc;
710	
711	    public Claims(JdbcTemplate jdbc) {
712	        this.jdbc = jdbc;
713	    }
714	
715	    /** The sheet's claims, newest first. */
716	    public List<Claim> list(String sheetId) {
717	        return jdbc.query("SELECT * FROM claim WHERE sheet_id = ? ORDER BY id DESC", ROW, sheetId);
718	    }
719	
720	    public Claim find(String sheetId, long id) {
721	        List<Claim> found = jdbc.query("SELECT * FROM claim WHERE sheet_id = ? AND id = ?", ROW, sheetId, id);
722	        return found.isEmpty() ? null : found.get(0);
723	    }
724	
725	    public Claim add(String sheetId, long personId, BigDecimal amount, LocalDate date, String note) {
726	        KeyHolder key = new GeneratedKeyHolder();
727	        jdbc.update(con -> {
728	            PreparedStatement ps = con.prepareStatement(
729	                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note) VALUES (?, ?, ?, ?, ?)",
730	                    new String[] { "id" });
731	            ps.setString(1, sheetId);
732	            ps.setLong(2, personId);
733	            ps.setBigDecimal(3, amount);
734	            ps.setDate(4, Date.valueOf(date));
735	            ps.setString(5, note);
736	            return ps;
737	        }, key);
738	        return new Claim(key.getKey().longValue(), sheetId, personId, amount, date, note, ClaimStatus.DRAFT, null, null, null,
739	                false, null);
740	    }
741	
742	    public void save(Claim claim) {
743	        jdbc.update("UPDATE claim SET amount = ?, claim_date = ?, note = ? WHERE id = ?", claim.amount(),
744	                Date.valueOf(claim.date()), claim.note(), claim.id());
745	    }
746	
747	    /**
748	     * Moves the claim to {@code next} if it still has its loaded status, and returns it as changed; null when
749	     * it has since changed. Opening gives it the sheet's next number; voiding clears its number. Settling
750	     * stores {@code due} as its fixed due (null keeps it live). Opening records {@code user} as its opener.
751	     */
752	    public Claim changeStatus(Claim claim, ClaimStatus next, BigDecimal due, String user) {
753	        if (jdbc.update("UPDATE claim SET status = ? WHERE id = ? AND status = ?", next.name(), claim.id(),
754	                claim.status().name()) != 1) {
755	            return null;
756	        }
757	        Long number = switch (next) {
758	            case OPEN -> nextNumber(claim.sheetId());
759	            case VOID -> null;
760	            default -> claim.number();
761	        };
762	        BigDecimal settledDue = next == ClaimStatus.SETTLED ? due : claim.settledDue();
763	        String openedBy = next == ClaimStatus.OPEN ? user : claim.openedBy();
764	        jdbc.update("UPDATE claim SET claim_number = ?, settled_due = ?, opened_by = ? WHERE id = ?", number,
765	                settledDue, openedBy, claim.id());
766	        return claim.withStatus(next, number, settledDue, openedBy);
767	    }
768	
769	    /**
770	     * Binds the person's claims to the figures of a statement: each claim in {@code figures} is stated at
771	     * its figure (null: n/a), and every other claim of theirs is left unbound.
772	     */
773	    public void bind(String sheetId, long personId, java.util.Map<Long, BigDecimal> figures) {
774	        jdbc.update("UPDATE claim SET stated = FALSE, stated_due = NULL WHERE sheet_id = ? AND person_id = ?",
775	                sheetId, personId);
776	        figures.forEach((id, figure) -> jdbc.update(
777	                "UPDATE claim SET stated = TRUE, stated_due = ? WHERE id = ?", figure, id));
778	    }
779	
780	    /**
781	     * The sheet's next claim number. The counter row is locked by the increment until the transaction
782	     * commits, so two claims opened at once get different numbers.
783	     */
784	    private long nextNumber(String sheetId) {
785	        try {
786	            jdbc.update("INSERT INTO claim_number_seq (sheet_id, last_number) SELECT ?, 0 "
787	                    + "WHERE NOT EXISTS (SELECT 1 FROM claim_number_seq WHERE sheet_id = ?)", sheetId, sheetId);
788	        } catch (DuplicateKeyException e) {
789	            // Another user started the sheet's counter at the same moment.
790	        }
791	        jdbc.update("UPDATE claim_number_seq SET last_number = last_number + 1 WHERE sheet_id = ?", sheetId);
792	        return jdbc.queryForObject("SELECT last_number FROM claim_number_seq WHERE sheet_id = ?", Long.class,
793	                sheetId);
794	    }
795	}
