1114	public class ValidateRate {
1115	
1116	    private static final Set<String> GRADES = Set.of("A", "B", "C");
1117	    private static final Pattern PERCENT = Pattern.compile("\\d{1,7}(\\.\\d{1,2})?");
1118	    private static final DateTimeFormatter ISO = DateTimeFormatter.ofPattern("uuuu-MM-dd")
1119	            .withResolverStyle(ResolverStyle.STRICT);
1120	
1121	    // The rate is kept with two decimals; a grade other than A, B or C, or a rate that is not a
1122	    // percent of 0.00 or more with up to two decimals, is refused. A blank from-date means from the
1123	    // beginning of time; one that is not a date (yyyy-mm-dd) is refused.
1124	    public void validate(@PathVariable("sheetId") String sheetId, @PathVariable("grade") String grade,
1125	            @RequestBody RateRequest body, Out<Rate> rateOut) throws InvalidRateException {
1126	        String g = grade == null ? "" : grade.trim();
1127	        String typed = body == null || body.rate() == null ? "" : body.rate().trim();
1128	        if (!GRADES.contains(g)) {
1129	            throw new InvalidRateException("The grade must be A, B or C.");
1130	        }
1131	        if (!PERCENT.matcher(typed).matches()) {
1132	            throw new InvalidRateException("The rate must be a percent of 0.00 or more, with up to two decimals.");
1133	        }
1134	        String typedFrom = body == null || body.from() == null ? "" : body.from().trim();
1135	        LocalDate from = null;
1136	        if (!typedFrom.isEmpty()) {
1137	            try {
1138	                from = LocalDate.parse(typedFrom, ISO);
1139	            } catch (DateTimeParseException e) {
1140	                throw new InvalidRateException("The from-date must be a date (yyyy-mm-dd).");
1141	            }
1142	        }
1143	        rateOut.set(new Rate(sheetId.trim(), g, new BigDecimal(typed).setScale(2, RoundingMode.UNNECESSARY), from));
1144	    }
1145	}
